  const PANEL_CSS = "/**\n * Refined Gemini — Popup Stylesheet\n * Streamlined minimalist UI aligned with ChatGPT Settings.\n *\n * Spacing follows a strict 4px grid (2px only for hairline insets) and the\n * minimum type size is 12px for legibility on non-Retina Windows displays.\n * Theme tokens resolve from `data-theme` on <html> (extension popup) or on the\n * Shadow DOM host (UserScript in-page panel), falling back to the OS scheme.\n */\n\n:root,\n:host {\n  --bg: #ffffff;\n  --surface: #f4f4f4;\n  --surface-hover: #ececec;\n  --seg-active-bg: #ffffff;\n  --seg-active-shadow: 0 1px 2px rgba(0, 0, 0, 0.10), 0 0 0 0.5px rgba(0, 0, 0, 0.06);\n\n  --text: #0d0d0d;\n  --text-sub: #5d5d5d;\n  --text-muted: #8f8f8f;\n\n  --border: rgba(13, 13, 13, 0.08);\n  --switch-off: #d9d9e3;\n  --switch-on: #0285ff;\n  --brand-bg: #0285ff;\n  --brand-fg: #ffffff;\n  --focus-ring: rgba(2, 133, 255, 0.55);\n\n  --notice-bg: #fff7e6;\n  --notice-fg: #8a5300;\n  --notice-border: rgba(196, 122, 0, 0.22);\n  --status-on: #10a37f;\n  --status-off: #8f8f8f;\n\n  --toast-bg: #0d0d0d;\n  --toast-fg: #ffffff;\n  --toast-action: #66b5ff;\n}\n\n:root[data-theme=\"dark\"],\n:host([data-theme=\"dark\"]) {\n  --bg: #212121;\n  --surface: #171717;\n  --surface-hover: #2a2a2a;\n  --seg-active-bg: #383838;\n  --seg-active-shadow: 0 1px 3px rgba(0, 0, 0, 0.35), 0 0 0 0.5px rgba(255, 255, 255, 0.08);\n\n  --text: #ececec;\n  --text-sub: #b4b4b4;\n  --text-muted: #8e8ea0;\n\n  --border: rgba(255, 255, 255, 0.09);\n  --switch-off: #424242;\n  --focus-ring: rgba(102, 181, 255, 0.7);\n\n  --notice-bg: rgba(255, 184, 0, 0.10);\n  --notice-fg: #f5c46b;\n  --notice-border: rgba(255, 184, 0, 0.22);\n\n  --toast-bg: #ececec;\n  --toast-fg: #0d0d0d;\n  --toast-action: #0169cc;\n}\n\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme]) {\n    --bg: #212121;\n    --surface: #171717;\n    --surface-hover: #2a2a2a;\n    --seg-active-bg: #383838;\n    --text: #ececec;\n    --text-sub: #b4b4b4;\n    --text-muted: #8e8ea0;\n    --border: rgba(255, 255, 255, 0.09);\n    --switch-off: #424242;\n  }\n}\n\n* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nhtml,\nbody {\n  background-color: var(--bg);\n}\n\nbody {\n  width: 320px;\n  max-width: 100%;\n  overflow-x: hidden;\n}\n\n.popup-shell {\n  position: relative;\n  padding: 12px 16px;\n  background-color: var(--bg);\n  color: var(--text);\n  font-family: ui-sans-serif, -apple-system, BlinkMacSystemFont, \"Segoe UI\",\n    \"PingFang SC\", \"Hiragino Sans GB\", \"Microsoft YaHei\", sans-serif;\n  font-size: 13px;\n  line-height: 1.4;\n  -webkit-font-smoothing: antialiased;\n  user-select: none;\n  text-align: left;\n}\n\nbutton {\n  font-family: inherit;\n}\n\n/* Unified keyboard focus ring (never shown for mouse clicks) */\n.popup-shell :focus {\n  outline: none;\n}\n\n.popup-shell :focus-visible,\n.switch input:focus-visible + .switch-track {\n  outline: none;\n  box-shadow: 0 0 0 2px var(--bg), 0 0 0 4px var(--focus-ring);\n}\n\n/* Header */\n.header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  padding-bottom: 12px;\n  border-bottom: 1px solid var(--border);\n}\n\n.brand {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  min-width: 0;\n}\n\n.brand-mark {\n  width: 28px;\n  height: 28px;\n  border-radius: 8px;\n  background: var(--brand-bg);\n  color: var(--brand-fg);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n  transition: background-color 0.16s ease;\n}\n\n.popup-shell.is-paused .brand-mark {\n  background: var(--switch-off);\n}\n\n.brand-text {\n  min-width: 0;\n}\n\n.brand-title {\n  font-size: 14px;\n  font-weight: 600;\n  letter-spacing: -0.01em;\n  line-height: 1.25;\n  color: var(--text);\n  white-space: nowrap;\n}\n\n.brand-status {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  font-size: 12px;\n  line-height: 1.3;\n  color: var(--text-sub);\n  white-space: nowrap;\n  min-width: 0;\n  overflow: hidden;\n}\n\n#statusLabel {\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.status-dot {\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background-color: var(--status-on);\n  flex-shrink: 0;\n  transition: background-color 0.16s ease;\n}\n\n.popup-shell.is-paused .status-dot {\n  background-color: var(--status-off);\n}\n\n.header-actions {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-shrink: 0;\n}\n\n/* Compact Language Switcher (中 | EN) */\n.lang-switch {\n  display: inline-flex;\n  align-items: center;\n  background-color: var(--surface);\n  padding: 2px;\n  border-radius: 8px;\n  gap: 2px;\n}\n\n.lang-btn {\n  appearance: none;\n  border: none;\n  background: transparent;\n  color: var(--text-sub);\n  font-size: 12px;\n  font-weight: 600;\n  line-height: 1;\n  min-width: 28px;\n  padding: 4px 6px;\n  border-radius: 6px;\n  cursor: pointer;\n  transition: background-color 0.14s ease, color 0.14s ease, box-shadow 0.14s ease;\n}\n\n.lang-btn:hover:not(.active) {\n  color: var(--text);\n}\n\n.lang-btn.active {\n  background-color: var(--seg-active-bg);\n  color: var(--text);\n  box-shadow: var(--seg-active-shadow);\n}\n\n/* Contextual notice */\n.notice {\n  display: flex;\n  align-items: flex-start;\n  gap: 8px;\n  margin-top: 12px;\n  padding: 8px 8px 8px 12px;\n  border-radius: 8px;\n  background-color: var(--notice-bg);\n  border: 1px solid var(--notice-border);\n  color: var(--notice-fg);\n  font-size: 12px;\n  line-height: 1.45;\n}\n\n.notice[hidden] {\n  display: none;\n}\n\n.notice[data-tone=\"info\"] {\n  background-color: var(--surface);\n  border-color: var(--border);\n  color: var(--text-sub);\n}\n\n.notice-icon {\n  flex-shrink: 0;\n  margin-top: 2px;\n}\n\n.notice-text {\n  flex: 1;\n  min-width: 0;\n}\n\n.notice-action {\n  appearance: none;\n  flex-shrink: 0;\n  border: none;\n  background: var(--bg);\n  color: var(--text);\n  font-size: 12px;\n  font-weight: 600;\n  padding: 2px 8px;\n  border-radius: 6px;\n  cursor: pointer;\n  box-shadow: 0 0 0 1px var(--border);\n  transition: background-color 0.12s ease;\n}\n\n.notice-action:hover {\n  background-color: var(--surface-hover);\n}\n\n.notice-action[hidden] {\n  display: none;\n}\n\n/* Settings Body */\n.settings-body {\n  padding-top: 12px;\n  transition: opacity 0.16s ease;\n}\n\n/* Paused: visually de-emphasized but still fully editable (pre-configure before resuming) */\n.settings-body.is-disabled {\n  opacity: 0.55;\n}\n\n.settings-body.is-disabled:hover,\n.settings-body.is-disabled:focus-within {\n  opacity: 0.85;\n}\n\n.group {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n/* Segmented Controls */\n.field-block {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n\n.field-label {\n  font-size: 12px;\n  font-weight: 500;\n  color: var(--text-sub);\n}\n\n.segmented {\n  display: flex;\n  background-color: var(--surface);\n  padding: 2px;\n  border-radius: 8px;\n  gap: 2px;\n}\n\n.seg-btn {\n  flex: 1;\n  min-width: 0;\n  appearance: none;\n  border: none;\n  background: transparent;\n  color: var(--text-sub);\n  font-size: 12px;\n  font-weight: 500;\n  line-height: 16px;\n  padding: 4px;\n  border-radius: 6px;\n  cursor: pointer;\n  transition: background-color 0.14s ease, color 0.14s ease, box-shadow 0.14s ease;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.seg-btn:hover:not(.active) {\n  color: var(--text);\n  background-color: var(--surface-hover);\n}\n\n.seg-btn.active {\n  background-color: var(--seg-active-bg);\n  color: var(--text);\n  box-shadow: var(--seg-active-shadow);\n}\n\n.divider {\n  height: 1px;\n  background-color: var(--border);\n  margin: 12px 0 8px;\n}\n\n/* Row Switches */\n.switches-list {\n  gap: 0;\n}\n\n.row-item {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  min-height: 32px;\n  padding: 4px 8px;\n  margin: 0 -8px;\n  border-radius: 8px;\n  cursor: pointer;\n  transition: background-color 0.12s ease;\n}\n\n.row-item:hover {\n  background-color: var(--surface);\n}\n\n.row-title {\n  font-size: 13px;\n  font-weight: 500;\n  color: var(--text);\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n}\n\nkbd {\n  display: inline-block;\n  min-width: 20px;\n  padding: 0 4px;\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 12px;\n  line-height: 18px;\n  text-align: center;\n  color: var(--text-sub);\n  background-color: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: 4px;\n}\n\n/* Toggle Switch */\n.switch {\n  position: relative;\n  display: inline-flex;\n  align-items: center;\n  cursor: pointer;\n  flex-shrink: 0;\n}\n\n.switch input {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  margin: 0;\n  opacity: 0;\n  cursor: pointer;\n}\n\n.switch-track {\n  width: 36px;\n  height: 20px;\n  background-color: var(--switch-off);\n  border-radius: 999px;\n  position: relative;\n  transition: background-color 0.16s ease, box-shadow 0.16s ease;\n}\n\n.switch-thumb {\n  position: absolute;\n  top: 2px;\n  left: 2px;\n  width: 16px;\n  height: 16px;\n  border-radius: 50%;\n  background-color: #ffffff;\n  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);\n  transition: transform 0.16s cubic-bezier(0.2, 0.8, 0.2, 1);\n}\n\n.switch input:checked + .switch-track {\n  background-color: var(--switch-on);\n}\n\n.switch input:checked + .switch-track .switch-thumb {\n  transform: translateX(16px);\n}\n\n.switch-sm .switch-track {\n  width: 32px;\n  height: 18px;\n}\n\n.switch-sm .switch-thumb {\n  width: 14px;\n  height: 14px;\n}\n\n.switch-sm input:checked + .switch-track .switch-thumb {\n  transform: translateX(14px);\n}\n\n/* Footer */\n.footer {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  min-height: 44px;\n  margin-top: 8px;\n  padding-top: 8px;\n  border-top: 1px solid var(--border);\n}\n\n.footer-hint {\n  flex: 1;\n  min-width: 0;\n  font-size: 12px;\n  line-height: 16px;\n  color: var(--text-muted);\n}\n\n#footerDefault {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n}\n\n#footerDefault[hidden],\n#footerHintText[hidden] {\n  display: none;\n}\n\n#footerHintText {\n  display: -webkit-box;\n  -webkit-line-clamp: 2;\n  -webkit-box-orient: vertical;\n  overflow: hidden;\n  color: var(--text-sub);\n}\n\n.shortcut-link {\n  appearance: none;\n  border: none;\n  background: transparent;\n  color: var(--text-muted);\n  font-size: 12px;\n  padding: 2px 4px;\n  margin: -2px -4px;\n  border-radius: 4px;\n  cursor: pointer;\n}\n\n.shortcut-link:hover {\n  color: var(--text);\n  background-color: var(--surface);\n}\n\n.shortcut-link[hidden] {\n  display: none;\n}\n\n.reset-btn {\n  appearance: none;\n  flex-shrink: 0;\n  border: none;\n  background: transparent;\n  color: var(--text-sub);\n  font-size: 12px;\n  font-weight: 500;\n  padding: 4px 8px;\n  margin-right: -8px;\n  border-radius: 6px;\n  cursor: pointer;\n  transition: background-color 0.12s ease, color 0.12s ease;\n}\n\n.reset-btn:hover {\n  background-color: var(--surface);\n  color: var(--text);\n}\n\n/* Undo toast */\n.toast {\n  position: absolute;\n  left: 12px;\n  right: 12px;\n  bottom: 12px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 8px 8px 8px 12px;\n  border-radius: 8px;\n  background-color: var(--toast-bg);\n  color: var(--toast-fg);\n  font-size: 12px;\n  font-weight: 500;\n  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.18);\n  animation: rg-toast-in 0.18s cubic-bezier(0.2, 0.8, 0.2, 1);\n}\n\n.toast[hidden] {\n  display: none;\n}\n\n.toast-action {\n  appearance: none;\n  border: none;\n  background: transparent;\n  color: var(--toast-action);\n  font-size: 12px;\n  font-weight: 600;\n  padding: 2px 8px;\n  border-radius: 4px;\n  cursor: pointer;\n}\n\n.toast-action:hover {\n  text-decoration: underline;\n}\n\n@keyframes rg-toast-in {\n  from {\n    opacity: 0;\n    transform: translateY(4px);\n  }\n  to {\n    opacity: 1;\n    transform: none;\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .popup-shell *,\n  .popup-shell *::before,\n  .popup-shell *::after {\n    transition-duration: 0.01ms !important;\n    animation-duration: 0.01ms !important;\n  }\n}\n\n:host {\n  all: initial;\n  position: fixed;\n  top: 64px;\n  right: 16px;\n  z-index: 2147483001;\n  display: block;\n}\n:host([hidden]) { display: none; }\n.popup-shell {\n  width: 320px;\n  max-height: calc(100vh - 88px);\n  overflow-y: auto;\n  border-radius: 16px;\n  border: 1px solid var(--border);\n  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.16), 0 2px 8px rgba(0, 0, 0, 0.06);\n  animation: rg-panel-in 0.16s cubic-bezier(0.2, 0.8, 0.2, 1);\n}\n@keyframes rg-panel-in {\n  from { opacity: 0; transform: translateY(-4px) scale(0.98); }\n  to { opacity: 1; transform: none; }\n}\n";
